mapper.insert:
INSERT INTO ck_shop_track_summary (id, stat_time, granularity, org_code, product_id, dim_type, dim_value, pv, uv, ip_count, visit_count, bounce_count, total_duration_ms, expose_count, click_count) SELECT REPLACE(UUID(), '-', ''), ${bucketExpr}, #{granularity}, ${orgExpr}, ${productExpr}, #{dimType}, ${dimValueExpr}, SUM(CASE WHEN e.event_name IN (#{pvEvent}, 'product_view') THEN 1 ELSE 0 END), COUNT(DISTINCT NULLIF(e.visitor_id, '')), COUNT(DISTINCT NULLIF(e.ip, '')), COUNT(DISTINCT NULLIF(e.session_id, '')), COUNT(DISTINCT CASE WHEN b.session_id IS NOT NULL THEN e.session_id END), COALESCE(SUM(e.duration_ms), 0), SUM(CASE WHEN e.event_name = 'product_expose' THEN 1 ELSE 0 END), SUM(CASE WHEN e.event_name = 'product_click' THEN 1 ELSE 0 END) FROM ck_shop_track_event e LEFT JOIN ( SELECT session_id FROM ck_shop_track_event WHERE event_name IN ('page_view', 'product_view') AND event_time >= #{start} AND event_time < #{end} GROUP BY session_id HAVING COUNT(1) = 1 ) b ON b.session_id = e.session_id WHERE e.event_time >= #{start} AND e.event_time < #{end}
AND e.product_id IS NOT NULL AND e.product_id <> ''
GROUP BY ${bucketExpr}, ${orgExpr}, ${productExpr}, ${dimValueExpr} ON DUPLICATE KEY UPDATE pv = VALUES(pv), uv = VALUES(uv), ip_count = VALUES(ip_count), visit_count = VALUES(visit_count), bounce_count = VALUES(bounce_count), total_duration_ms = VALUES(total_duration_ms), expose_count = VALUES(expose_count), click_count = VALUES(click_count)

mapper.select:
SELECT *
FROM ck_shop_track_summary
WHERE dim_type = #{dimType}
AND granularity = #{granularity}
AND stat_time >= #{start}
AND stat_time < #{end}
AND dim_value LIKE CONCAT(#{dimValuePrefix}, '%')

ORDER BY stat_time ASC
